async (page) => {
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  const base = 'http://127.0.0.1:8769/prototype-decisions.html?variant=C';
  const out = 'docs/design-review/';
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto(base);
  await page.getByRole('heading', { name: 'Índice de decisões', exact: true }).waitFor();
  await page.screenshot({ path: out + 'decisions-c-polished.png' });
  const railOnRight = await page.evaluate(() => {
    const reader = document.querySelector('.chronicle > .reader').getBoundingClientRect();
    const index = document.querySelector('.chronicle > .index').getBoundingClientRect();
    return index.left >= reader.right - 1;
  });
  if (!railOnRight) throw new Error('O índice deve permanecer à direita do documento');
  await page.getByRole('button', { name: 'Expandir leitura', exact: true }).click();
  await page.getByRole('dialog').getByText('transaction.begin();', { exact: false }).waitFor();
  await page.screenshot({ path: out + 'decisions-c-source-expanded.png' });
  await page.getByRole('button', { name: 'Fechar', exact: true }).click();
  await page.getByRole('button', { name: 'captura.txt', exact: true }).click();
  await page.getByText('A escolha foi discutida na sessão e confirmada após revisão humana.', { exact: false }).waitFor();
  await page.getByRole('button', { name: 'Histórico', exact: false }).click();
  await page.getByRole('button', { name: 'v2', exact: true }).click();
  await page.getByText('Versão anterior · somente leitura.', { exact: false }).waitFor();
  await page.screenshot({ path: out + 'decisions-c-history.png' });
  await page.getByRole('button', { name: 'Exportar…', exact: true }).click();
  await page.locator('#format').selectOption('JSON');
  if (JSON.parse(await page.locator('#exportPreview').textContent()).version !== 3) throw new Error('Preview deve exportar a versão atual');
  await page.getByRole('button', { name: 'Cancelar', exact: true }).click();
  await page.getByRole('textbox', { name: 'Buscar decisões do projeto', exact: true }).fill('cofre');
  await page.getByRole('heading', { name: 'Onde armazenar credenciais do provedor?', exact: true }).waitFor();
  await page.getByRole('textbox', { name: 'Buscar decisões do projeto', exact: true }).fill('zzzznenhuma');
  await page.getByText('Nenhuma decisão encontrada', { exact: true }).waitFor();
  await page.screenshot({ path: out + 'decisions-c-empty.png' });
  await page.setViewportSize({ width: 1180, height: 760 });
  await page.goto(base);
  await page.screenshot({ path: out + 'decisions-c-compact.png' });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  if (overflow) throw new Error('Janela compacta com overflow horizontal');
  await page.getByRole('button', { name: 'Revisar', exact: true }).click();
  await page.getByRole('dialog').getByRole('textbox').first().waitFor();
  await page.getByRole('button', { name: 'Cancelar', exact: true }).click();
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto(base);
  if (errors.length) throw new Error(errors.join('\n'));
  return { variant: 'C', checks: ['índice à direita', 'leitura ampliada', 'troca de fonte', 'histórico somente leitura', 'export da versão atual', 'busca e vazio', '1180x760 sem overflow', 'formulário e cancelamento'], errors };
}
